import{z as d,x as B,o as l,c as p,q as E,j as s,D as t,d as o,s as n,S as i,b as e}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"RWKV-7 Goose","description":"","frontmatter":{"title":"RWKV-7 Goose","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/rwkv-7-goose.md","filePath":"llm/rwkv-7-goose.md","lastUpdated":1791063341000}'),A={name:"llm/rwkv-7-goose.md"};function m(h,a,_,D,k,C){const r=B("Mermaid");return l(),p("div",null,[a[2]||(a[2]=E('<h1 id="rwkv-7-goose" tabindex="-1">RWKV-7 Goose <a class="header-anchor" href="#rwkv-7-goose" aria-label="Permalink to &quot;RWKV-7 Goose&quot;">​</a></h1><div class="epigraph"><p>把 delta 规则推广成向量门控、向量学习率与解耦的擦除 / 写入键之后，常状态 RNN 可以做状态跟踪、识别所有正则语言，同时训练仍可并行。</p><footer>—— Peng, Zhang, Goldstein 等，RWKV-7 &quot;Goose&quot; with Expressive Dynamic State Evolution，arXiv:2503.14456</footer></div><p><a href="/llm/rwkv">RWKV</a> 第四代把时间混合收成带通道衰减的 WKV，推理常数状态、训练可并行。第五代矩阵状态、第六代数据依赖对角衰减，仍是「衰减整表 + 外积写入」：<a href="/llm/delta-net">DeltaNet</a> 指出衰减不能按键擦除。Bo Peng、Ruichong Zhang、Daniel Goldstein 等人的 <strong>RWKV-7「Goose」</strong> 把转移写成广义 delta：</p> \\[S_t=S_{t-1}\\bigl(\\mathrm{diag}(w_t)-\\hat\\kappa_t^\\top(a_t\\odot\\hat\\kappa_t)\\bigr)+v_t^\\top k_t. \\]<p>2.9B 模型在少得多的 token 上拿到当时 3B 多语 SoTA，英语下游打平同档 SoTA。语料是开源 <strong>RWKV World v3（3.1T）</strong>；发布 0.19B–2.9B 四档 World，以及 Pile 上 0.17B–1.47B 对照档。权重与数据清单在 Hugging Face <code>RWKV</code>，代码 <code>RWKV/RWKV-LM</code>，Apache 2.0。本篇写广义 delta 与表达力，不把后续 G1 推理档的额外 1T 数据写进主实验。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Softmax 注意力二次缓存；线性注意力 / SSM 把历史压进固定 \\(S\\)，却长期在「只加不减」或「整表衰减」里打转。RWKV-6 与 GLA 的 \\(S_t=S_{t-1}\\mathrm{diag}(w_t)+v_t^\\top k_t\\) 能淡化，不能按地址替换。DeltaNet 按当前键做秩一覆盖，学习率却是标量，擦除键与写入键相同。<a href="/llm/gated-delta-net">Gated DeltaNet</a> 再乘头级标量门，仍不是通道级替换。</p><p><span class="marginnote">数字实例：4k 上下文时，标准注意力要为每个头缓存随长度增长的 KV 表；RWKV-7 每头只存约 \\(64\\times64\\) 的状态矩阵——上下文涨到 10 万 token，这份状态也一动不动。省的是显存和每步计算，代价是历史必须被压缩进这块固定草稿纸。</span></p><p>第二条缺口是表达力。对角转移的线性 RNN 与 Transformer 在标准猜想下困在 \\(\\mathsf{TC}^0\\)，做不了需要状态跟踪的正则语言（奇偶、括号）。Grazzi 等人指出负特征值能打开一截；RWKV-7 要证明的是更强命题：广义 delta 在常数层内识别<strong>所有</strong>正则语言，且单层可解 \\(S_5\\) 状态跟踪（属 \\(\\mathsf{NC}^1\\)）。同时训练必须仍是对角加秩一，以便沿时间分块并行。</p><h3 id="广义-delta-比经典-delta-多了什么" tabindex="-1">广义 delta 比经典 delta 多了什么 <a class="header-anchor" href="#广义-delta-比经典-delta-多了什么" aria-label="Permalink to &quot;广义 delta 比经典 delta 多了什么&quot;">​</a></h3><p>经典：\\(S_t=S_{t-1}(I-a k^\\top k)+a v^\\top k\\)。Goose 把衰减换成向量 \\(w_t\\)，把学习率换成向量 \\(a_t\\in(0,1)^D\\)，并把擦除方向 \\(\\kappa\\) 与写入键 \\(k\\) 分开。参数化 \\(z_t=-\\hat\\kappa_t\\)、\\(b_t=\\hat\\kappa_t\\odot a_t\\)，落在作者给出的稳定域里（附录 C）。于是每个通道可以独立决定「这段状态留多少、沿哪把钥匙挖掉」。隐含位置偏置来自数据依赖的对角门，不必另加 RoPE。</p><p><span class="marginnote">表 1 把 RWKV-7 标成同时具备大状态、灵活衰减、动态依赖、广义特征值（GE）。预训大模型里负特征值只放开一部分，因为实验观察到不稳。复现「超出 TC⁰」要用附录证明设定，不要默认生产权重已打开全谱负根。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>时间混合仍从 token-shift 出发，但去掉对 \\(x_{t-1}\\) 的数据依赖插值系数，改为固定 \\(\\mu\\) 的 lerp，加快训练。\\(r,k,v,w,a,g\\) 等多用低秩 MLP（loramlp）从 \\(x\\) 生成，在参数量、速度与下游之间折中。通道混合去掉 receptance 门，保留 \\(\\mathrm{ReLU}^2\\) 前馈。架构继承 bonus 等 RWKV-6 零件，主替换发生在状态转移。</p><p>状态按头是 \\(64\\times 64\\) 量级矩阵（图示 4×4 只是示意）。更新先按 \\(w_t\\) 对角衰减，再沿归一化擦除键 \\(\\hat\\kappa_t\\) 做通道加权的秩一扣除，最后写入 \\(v_t^\\top k_t\\)。这仍是 DPLR，Yang 等人的分块并行可以延拓。World v3 加强英语、代码与多语；四档 World 训练 token 从 1.6T 到 5.6T 不等，2.9B 并不是从零吃满 5.6T——作者强调可从 RWKV-5/6 升级权重，降低重训成本。Pile 档用 GPT-NeoX 词表，方便与其它架构对齐。</p><p>表达力：非对角、输入依赖的转移能表示 copy 型状态迁移（Lemma 3），这是「常数层识别全部正则语言」证明的关键元件。训练并行与 \\(\\mathsf{NC}^1\\) 级跟踪可以同时成立，因为并行的是数值扫描，不是电路深度上的 \\(\\mathsf{TC}^0\\) 上限消失——论文把可并行训练与超 \\(\\mathsf{TC}^0\\) 的可表示性写成两件分开的事。</p>',16)),(l(),s(i,null,{default:t(()=>[n(r,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22x_t%2C%20x_%7Bt-1%7D%20lerp%22%5D%20--%3E%20GEN%5B%22loramlp%EF%BC%9Aw%2C%20a%2C%20%CE%BA%2C%20k%2C%20v%2C%20r%22%5D%0A%20%20GEN%20--%3E%20UPD%5B%22S_t%20%3D%20S_%7Bt-1%7D(diag(w)%20%E2%88%92%20%CE%BA%CC%82%E1%B5%80(a%E2%8A%99%CE%BA%CC%82))%20%2B%20v%E1%B5%80k%22%5D%0A%20%20UPD%20--%3E%20MIX%5B%22%E6%97%B6%E9%97%B4%E6%B7%B7%E5%90%88%20%2B%20ReLU%C2%B2%20%E9%80%9A%E9%81%93%E6%B7%B7%E5%90%88%22%5D%0A%20%20MIX%20--%3E%20Y%5B%22%E8%BE%93%E5%87%BA%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h3",{id:"升级权重不是免费午餐",tabindex:"-1"},[o("升级权重不是免费午餐 "),e("a",{class:"header-anchor",href:"#升级权重不是免费午餐","aria-label":'Permalink to "升级权重不是免费午餐"'},"​")],-1)),a[4]||(a[4]=e("p",null,"从 5/6 升 7，结构变了，不是换一层名字。作者把它当作降低计算的工程路径：先继承已有 World 表示，再在新转移上继续训。引用「更少 token 达到 3B SoTA」必须对着论文的对照表，不能把升级路径理解成零数据。多语 SoTA 与英语「打平」是 2.9B 档的陈述；0.19B 档不要套这句。",-1)),a[5]||(a[5]=e("h2",{id:"机制",tabindex:"-1"},[o("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=e("p",null,"衰减只能按通道淡化所有键上的值；delta 按键覆盖。Goose 把两者乘进同一转移，并允许擦除键 ≠ 写入键：模型可以「在 \\(\\kappa\\) 方向挖掉旧内容、在 \\(k\\) 方向写入新内容」，减少「覆盖 A 却弄脏 A 的邻居」的强迫对齐。向量 \\(a_t\\) 让有的通道快换、有的慢换，类似于 KDA 的通道遗忘，但 RWKV-7 仍是纯 RNN 主干，没有周期性 softmax 层。",-1)),(l(),s(i,null,{default:t(()=>[n(r,{id:"mermaid-57",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22%E7%8A%B6%E6%80%81%E7%9F%A9%E9%98%B5%20S%20%E7%9A%84%E4%B8%89%E7%A7%8D%E6%9B%B4%E6%96%B0%E6%96%B9%E5%BC%8F%22%5D%20--%3E%20DEC%5B%22%E5%AF%B9%E8%A7%92%E8%A1%B0%E5%87%8F%EF%BC%9A%E6%95%B4%E8%A1%A8%E4%B9%98%20w%22%5D%0A%20%20DEC%20--%3E%20P1%5B%22%E5%8F%AA%E8%83%BD%E6%95%B4%E4%BD%93%E6%B7%A1%E5%8C%96%EF%BC%8C%E6%93%A6%E4%B8%8D%E6%8E%89%E6%8C%87%E5%AE%9A%E5%9C%B0%E5%9D%80%22%5D%0A%20%20S%20--%3E%20DL%5B%22%E7%BB%8F%E5%85%B8%20delta%EF%BC%9A%E6%B2%BF%E9%94%AE%20k%20%E7%A7%A9%E4%B8%80%E8%A6%86%E7%9B%96%22%5D%0A%20%20DL%20--%3E%20P2%5B%22%E8%83%BD%E6%8C%89%E9%94%AE%E6%9B%BF%E6%8D%A2%EF%BC%8C%E4%BD%86%E5%AD%A6%E4%B9%A0%E7%8E%87%E6%98%AF%E6%A0%87%E9%87%8F%22%5D%0A%20%20S%20--%3E%20GO%5B%22%E5%B9%BF%E4%B9%89%20delta%EF%BC%9A%E5%90%91%E9%87%8F%20w%20%E5%8A%A0%E5%90%91%E9%87%8F%20a%22%5D%0A%20%20GO%20--%3E%20P3%5B%22%E6%AF%8F%E4%B8%AA%E9%80%9A%E9%81%93%E7%8B%AC%E7%AB%8B%E5%86%B3%E5%AE%9A%E7%95%99%E5%A4%9A%E5%B0%91%22%5D%0A%20%20GO%20--%3E%20P4%5B%22%E6%93%A6%E9%99%A4%E9%94%AE%20%CE%BA%20%E4%B8%8E%E5%86%99%E5%85%A5%E9%94%AE%20k%20%E5%8F%AF%E4%BB%A5%E4%B8%8D%E5%90%8C%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=E('<p><span class="marginnote">直觉类比：擦除键与写入键解耦，就像一块白板可以「用板擦擦掉第 3 行，再用另一支笔写到第 5 行」；经典 delta 是擦和写必须用同一把尺子对准同一行，想覆盖一处就得连累旁边的字。</span></p><p>Token-shift 提供一阶短程混合，减轻状态里塞句法的压力。去掉通道混合的 receptance，是速度选择：门控表达力让给时间混合里的 \\(g\\)。低秩生成 \\(w,a\\) 限制了每步能写多大的满秩修正，这是带宽税：存几个 \\(D\\) 维向量，而不是存 \\(D\\times D\\) 的任意转移。</p><p><span class="marginnote">RWKV-7 与 Titans / TTT 同时期。后两者用动量 SGD 与分块更新；Goose 坚持逐步广义 delta 以便 RNN 推理逐步常数时间。不要把「测试时学习」写成 Goose 的默认叙事。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><h3 id="常数状态仍会撞容量" tabindex="-1">常数状态仍会撞容量 <a class="header-anchor" href="#常数状态仍会撞容量" aria-label="Permalink to &quot;常数状态仍会撞容量&quot;">​</a></h3><p>3B 多语领先不能外推到「已替代 70B Transformer」。有限 \\(64\\times 64\\) 每头在百万 token 精确针上仍可能糊。混合架构（Kimi Linear、Qwen3-Next）把少数满注意力层当保险；Goose 论文主线是纯 RNN。负特征值与正则语言证明在附录，生产权重为稳定性收紧了谱，工程实现若打开全谱需自己看损失尖峰。</p><p><span class="marginnote">常见误区：以为「常数状态」等于「无限记忆」。\\(64\\times64\\) 的状态是固定大小的草稿纸——写下一段时旧内容会被压缩与覆盖，这正是百万 token「大海捞针」类测试可能糊掉的原因，也是混合架构要加回满注意力层当保险的理由。</span></p><p>许可与出处：Linux Foundation AI &amp; Data 下的 RWKV 项目，EleutherAI / Recursal 等共同作者。Wiki 将架构代号记为 Goose，论文 2025-03-18 首发、03-30 v2。引用公式以 arXiv:2503.14456 表 1 与 §4 为准。World 与 Pile 两套词表不要混评：Pile 档是为了和 GPT-NeoX 生态对齐，多语 SoTA 只属于 World v3 的 2.9B。推理逐步常数时间在 batch=1 时最明显；大 batch 训练仍靠时间维并行扫描，墙钟取决于核，而不是渐近记号本身。</p><p><span class="marginnote">出处：Peng, Zhang, Goldstein, Alcaide, Merrill 等，<em>RWKV-7 &quot;Goose&quot; with Expressive Dynamic State Evolution</em>，arXiv:2503.14456。前代见 Peng et al. EMNLP 2023（RWKV-4）与 RWKV-6 技术报告。Delta 并行见 Yang et al. NeurIPS 2024。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Goose 用向量门控、向量学习率与解耦擦除键推广 delta 规则。</li><li>推理逐步常数时间与内存；转移仍是 DPLR，训练可分块并行。</li><li>表达力在标准猜想下超出 Transformer 的 \\(\\mathsf{TC}^0\\)，可识别全部正则语言。</li><li>World v3 3.1T；2.9B 多语 3B SoTA、英语打平同档。</li><li>出处：Peng et al.，arXiv:2503.14456。</li></ul>',11))])}const T=d(A,[["render",m]]);export{u as __pageData,T as default};
